#include "gdc_api.h"

typedef struct pattern_y_s {
	char color_y;
	int len_pixel;
} pattern_y_t;

typedef struct pattern_uv_s {
	char color_u;
	char color_v;
	int len_pixel;
} pattern_uv_t;

typedef struct patern_input_image {
	int image_w;
	int image_h;
	pattern_y_t y[4];
	pattern_uv_t uv[4];
} patern_input_image_t;

typedef struct patern_output_image {
	int version;
	int image_w;
	int image_h;
	int y_array_cnt;
	int uv_array_cnt;
	pattern_y_t *y;
	pattern_uv_t *uv;
} patern_output_image_t;

